HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#07111f"><title>Jarvis</title><style>:root{--bg:#06101d;--panel:#0d1a2d;--line:#25415f;--text:#eef6ff;--muted:#91a9c4;--green:#48d8a0;--red:#ff7288}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#15365d 0,#07111f 38%,#040a12 100%);color:var(--text);font:16px system-ui;min-height:100vh}.wrap{max-width:1360px;margin:auto;padding:22px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.brand h1{margin:0;font-size:26px;letter-spacing:.06em}.brand small,.muted,.notice{color:var(--muted)}.status{display:flex;align-items:center;gap:9px;font-weight:750;color:var(--muted)}.dot{width:10px;height:10px;border-radius:50%;background:#ffbd59;box-shadow:0 0 18px currentColor}.dot.online{background:var(--green)}.card{background:linear-gradient(180deg,rgba(17,32,54,.96),rgba(10,23,40,.96));border:1px solid var(--line);border-radius:22px;box-shadow:0 20px 55px rgba(0,0,0,.22)}.login{max-width:580px;margin:9vh auto;padding:28px}.login input{width:100%;padding:16px;border-radius:13px;border:1px solid #365675;background:#07111f;color:#fff;font-size:17px}.btn{border:0;border-radius:13px;padding:13px 17px;background:#1a2d48;color:#eaf4ff;font-weight:800;cursor:pointer}.btn.primary{background:linear-gradient(135deg,#3283ff,#4f9cff)}.btn.green{background:#143f36;color:#bff4df}.hidden{display:none!important}.shell{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,.75fr);gap:18px}.conversation{min-height:720px;display:flex;flex-direction:column;overflow:hidden}.stage{padding:30px 24px 16px;display:flex;flex-direction:column;align-items:center;text-align:center;border-bottom:1px solid rgba(62,94,128,.5)}.orb-wrap{height:220px;display:flex;align-items:center;justify-content:center}.orb{width:142px;height:142px;border-radius:50%;position:relative;background:radial-gradient(circle at 35% 30%,#d7fbff 0,#62dfff 9%,#177ec7 34%,#11264d 68%,#07101f 100%);box-shadow:0 0 35px rgba(80,216,255,.34),0 0 90px rgba(61,140,255,.2);transition:.3s}.orb:before,.orb:after{content:"";position:absolute;inset:-17px;border:1px solid rgba(80,216,255,.25);border-radius:50%}.orb:after{inset:-35px;opacity:.35}.orb.listening{animation:pulse 1.2s infinite;box-shadow:0 0 40px rgba(72,216,160,.5),0 0 100px rgba(72,216,160,.24)}.orb.thinking{animation:spinGlow 1.8s linear infinite}.orb.speaking{animation:speak 650ms ease-in-out infinite alternate;box-shadow:0 0 55px rgba(80,216,255,.65),0 0 120px rgba(61,140,255,.32)}.orb.error{filter:hue-rotate(120deg)}@keyframes pulse{50%{transform:scale(1.07)}}@keyframes speak{to{transform:scale(1.055);filter:brightness(1.18)}}@keyframes spinGlow{50%{filter:hue-rotate(35deg) brightness(1.18);transform:scale(1.03)}}.state{font-size:22px;font-weight:850;margin-top:6px}.substate{color:var(--muted);margin-top:6px;min-height:24px}.wake{margin-top:18px;display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap}.badge{border:1px solid #31506e;border-radius:999px;padding:8px 12px;color:#a9bed4;background:#0a1728}.badge.on{color:#c7f9e6;border-color:#28715a;background:#0c2b25}.transcript{flex:1;overflow:auto;padding:22px;display:flex;flex-direction:column;gap:12px;min-height:290px;max-height:420px}.msg{max-width:84%;padding:13px 15px;border-radius:16px;line-height:1.45;white-space:pre-wrap}.msg.user{align-self:flex-end;background:#2466c7}.msg.jarvis{align-self:flex-start;background:#152943;border:1px solid #2c4969}.msg.system{align-self:center;background:transparent;color:var(--muted);font-size:14px}.composer{padding:16px;border-top:1px solid rgba(62,94,128,.5);display:grid;grid-template-columns:auto 1fr auto;gap:10px}.composer textarea{resize:none;min-height:54px;max-height:120px;padding:14px;border-radius:14px;border:1px solid #365675;background:#07111f;color:white;font:inherit}.mic{width:54px;height:54px;border-radius:50%;font-size:22px}.send{min-width:92px}.helper{padding:0 18px 16px;color:var(--muted);font-size:13px}.side{display:flex;flex-direction:column;gap:18px}.side .card{padding:20px}.side h2{font-size:19px;margin:0 0 14px}.metric{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.metric div{padding:12px;border-radius:13px;background:#0a1728;border:1px solid #233e5b}.metric b{display:block;font-size:22px}.metric span{color:var(--muted);font-size:13px}.objective-list{max-height:300px;overflow:auto}.objective{padding:11px 0;border-bottom:1px solid #223d59}.objective small{color:var(--muted)}.toolrow{display:flex;gap:9px;flex-wrap:wrap}.notice{font-size:14px;line-height:1.45}.error{color:var(--red)}@media(max-width:900px){.shell{grid-template-columns:1fr}.conversation{min-height:640px}.side{order:2}.orb-wrap{height:180px}.orb{width:118px;height:118px}.transcript{max-height:none;min-height:250px}.wrap{padding:12px}.composer{grid-template-columns:auto 1fr}.send{grid-column:2}.msg{max-width:92%}}</style></head><body><div class="wrap"><div class="top"><div class="brand"><h1>JARVIS <span id="ver"></span></h1><small>Autonomous Operations Agent</small></div><div class="status"><span id="dot" class="dot"></span><span id="rt">Connecting…</span></div></div><div id="login" class="card login"><h2>Owner Access</h2><p class="notice">Secure access to Jarvis.</p><input id="pw" type="password" placeholder="Owner password" autocomplete="current-password"><p><button id="loginBtn" class="btn primary">Open Jarvis</button></p><div id="loginErr" class="error"></div></div><div id="app" class="shell hidden"><section class="card conversation"><div class="stage"><div class="orb-wrap"><div id="orb" class="orb"></div></div><div id="state" class="state">Ready</div><div id="substate" class="substate">Say “Jarvis” or tap the microphone.</div><div class="wake"><button id="wakeBtn" class="btn green">Enable “Jarvis” wake word</button><span id="wakeBadge" class="badge">Wake word off</span><span class="badge on">British voice</span></div></div><div id="transcript" class="transcript"><div class="msg system">Jarvis is ready. Voice wake word requires microphone permission and a supported browser.</div></div><div class="composer"><button id="micBtn" class="btn mic" title="Talk to Jarvis">🎙</button><textarea id="input" placeholder="Talk to Jarvis…" rows="1"></textarea><button id="sendBtn" class="btn primary send">Send</button></div><div class="helper">Conversation is immediate. For autonomous work, use <b>Run as objective</b> after typing a task. Wake word: <b>Jarvis</b>.</div><div style="padding:0 16px 16px;display:flex;gap:9px;flex-wrap:wrap"><button id="objectiveBtn" class="btn">Run as objective</button><button id="stopVoiceBtn" class="btn">Stop voice</button><button id="clearBtn" class="btn">Clear conversation</button></div></section><aside class="side"><div class="card"><h2>Runtime</h2><div class="metric"><div><b id="running">0</b><span>running</span></div><div><b id="queued">0</b><span>queued</span></div><div><b id="blocked">0</b><span>blocked</span></div><div><b id="complete">0</b><span>complete</span></div></div><p id="runtimeDetail" class="notice"></p></div><div class="card"><h2>Systems</h2><div class="toolrow"><button id="modelBtn" class="btn">Test AI</button><button id="connBtn" class="btn">Test GitHub + Render</button></div><p id="testResult" class="notice"></p></div><div class="card"><h2>Objectives</h2><div id="objectives" class="objective-list"><span class="notice">Loading…</span></div></div></aside></div></div><script>
const $=id=>document.getElementById(id);let pollTimer=null,history=[],recognition=null,wakeEnabled=false,armed=false,manualListen=false,currentAudio=null,speechBusy=false;
async function api(url,options={}){const res=await fetch(url,{...options,cache:'no-store'});let data={};const ct=res.headers.get('content-type')||'';if(ct.includes('json'))data=await res.json();if(res.status===401){showLogin();throw new Error(data.detail||'Owner login required')}if(!res.ok)throw new Error(data.detail||data.error||`HTTP ${res.status}`);return data}
function showLogin(){$('login').classList.remove('hidden');$('app').classList.add('hidden')}function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden')}function setState(name,detail='',kind='idle'){$('state').textContent=name;$('substate').textContent=detail;$('orb').className='orb'+(kind!=='idle'?' '+kind:'')}function addMsg(role,text){const d=document.createElement('div');d.className='msg '+role;d.textContent=text;$('transcript').appendChild(d);$('transcript').scrollTop=$('transcript').scrollHeight;if(role==='user'||role==='jarvis'){history.push({role:role==='jarvis'?'assistant':'user',content:text});history=history.slice(-16)}}
async function boot(){try{const d=await api('/client/bootstrap');$('ver').textContent='v'+d.version.split('.')[0];if(d.authenticated){showApp();setOnline(true,'Agent online');startPoll();setState('Ready','Say “Jarvis” or tap the microphone.')}else{showLogin();$('rt').textContent='Owner login required'}}catch(e){$('rt').textContent='Backend unavailable';$('loginErr').textContent=e.message;setOnline(false)}}function setOnline(ok,label){$('dot').className='dot'+(ok?' online':'');$('rt').textContent=label||(ok?'Agent online':'Offline')}async function login(){try{$('loginErr').textContent='';await api('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('pw').value='';showApp();setOnline(true,'Agent online');startPoll()}catch(e){$('loginErr').textContent=e.message}}
async function sendConversation(text){text=(text||$('input').value).trim();if(!text||speechBusy)return;$('input').value='';addMsg('user',text);setState('Thinking','Working on your request…','thinking');speechBusy=true;try{const d=await api('/assistant/message',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:text,history:history.slice(0,-1)})});const reply=d.reply||'I am here.';addMsg('jarvis',reply);await speak(reply)}catch(e){addMsg('system','Error: '+e.message);setState('Error',e.message,'error')}finally{speechBusy=false;if(!currentAudio)setState('Ready',wakeEnabled?'Listening for “Jarvis”.':'Tap the microphone or type a message.')}}async function runObjective(){const text=$('input').value.trim();if(!text){addMsg('system','Type an objective first.');return}try{const d=await api('/agent/v223/command',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text,request_id:crypto.randomUUID()})});addMsg('system',d.message);$('input').value='';poll()}catch(e){addMsg('system','Objective error: '+e.message)}}
async function speak(text){stopVoice(false);setState('Speaking','Jarvis is responding…','speaking');try{const res=await fetch('/voice/tts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text})});if(!res.ok)throw new Error('Server voice unavailable');const blob=await res.blob(),url=URL.createObjectURL(blob);currentAudio=new Audio(url);currentAudio.onended=()=>{URL.revokeObjectURL(url);currentAudio=null;setState('Ready',wakeEnabled?'Listening for “Jarvis”.':'Tap the microphone or type a message.');resumeRecognition()};currentAudio.onerror=()=>{currentAudio=null;browserSpeak(text)};pauseRecognition();await currentAudio.play()}catch(e){browserSpeak(text)}}function browserSpeak(text){if(!('speechSynthesis'in window)){setState('Ready','Voice unavailable on this browser.');return}const u=new SpeechSynthesisUtterance(text),voices=speechSynthesis.getVoices();u.voice=voices.find(v=>/en-GB/i.test(v.lang)&&/daniel|serena|oliver|arthur|uk|brit/i.test(v.name))||voices.find(v=>/en-GB/i.test(v.lang))||null;u.lang='en-GB';u.rate=.96;u.pitch=.96;u.onend=()=>{setState('Ready',wakeEnabled?'Listening for “Jarvis”.':'Tap the microphone or type a message.');resumeRecognition()};speechSynthesis.speak(u)}function stopVoice(reset=true){if(currentAudio){currentAudio.pause();currentAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel();if(reset)setState('Ready',wakeEnabled?'Listening for “Jarvis”.':'Voice stopped.')}
function setupRecognition(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return false;recognition=new SR();recognition.lang='en-GB';recognition.continuous=true;recognition.interimResults=true;recognition.maxAlternatives=1;recognition.onstart=()=>{if(!speechBusy&&!currentAudio)setState(manualListen?'Listening':'Wake word armed',manualListen?'Speak now…':'Say “Jarvis”…','listening')};recognition.onresult=e=>{let final='',interim='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)final+=t;else interim+=t}if(interim&&!speechBusy)$('substate').textContent=interim;if(final)handleSpeech(final.trim())};recognition.onerror=e=>{if(e.error==='not-allowed'||e.error==='service-not-allowed'){wakeEnabled=false;$('wakeBadge').textContent='Microphone blocked';$('wakeBadge').className='badge';setState('Microphone permission needed','Allow microphone access in your browser settings.','error')}};recognition.onend=()=>{if((wakeEnabled||manualListen)&&!speechBusy&&!currentAudio)setTimeout(startRecognition,450)};return true}function startRecognition(){if(!recognition&&!setupRecognition()){setState('Voice input unsupported','Use Chrome, Edge, or Safari with speech recognition support.','error');return}try{recognition.start()}catch(e){}}function pauseRecognition(){if(recognition){try{recognition.stop()}catch(e){}}}function resumeRecognition(){if(wakeEnabled||manualListen)setTimeout(startRecognition,500)}function handleSpeech(text){const low=text.toLowerCase();if(manualListen){manualListen=false;sendConversation(text);return}const idx=low.indexOf('jarvis');if(idx>=0){const after=text.slice(idx+6).replace(/^[,\s:.-]+/,'').trim();armed=true;if(after){armed=false;sendConversation(after)}else setState('Yes?','I’m listening.','listening')}else if(armed){armed=false;sendConversation(text)}}function toggleWake(){wakeEnabled=!wakeEnabled;$('wakeBadge').textContent=wakeEnabled?'Wake word on':'Wake word off';$('wakeBadge').className='badge'+(wakeEnabled?' on':'');$('wakeBtn').textContent=wakeEnabled?'Disable “Jarvis” wake word':'Enable “Jarvis” wake word';if(wakeEnabled){startRecognition();setState('Wake word armed','Say “Jarvis”…','listening')}else{pauseRecognition();setState('Ready','Tap the microphone or type a message.')}}function manualMic(){manualListen=true;startRecognition();setState('Listening','Speak now…','listening')}
async function poll(){try{const s=await api('/agent/status');setOnline(true,s.worker_alive?'Agent online':'Supervisor recovering');$('running').textContent=s.running;$('queued').textContent=s.queued;$('blocked').textContent=s.blocked;$('complete').textContent=s.completed;$('runtimeDetail').textContent=`Supervisor ${s.worker_alive?'online':'recovering'} · watchdog ${s.watchdog_alive?'online':'recovering'} · DB ${s.database_ok?'ready':'error'}`;const o=await api('/agent/objectives');$('objectives').innerHTML=o.slice(0,12).map(x=>`<div class="objective"><b>#${x.id} ${esc(x.title)}</b><br><small>${esc(x.state)} · cycle ${x.step}/${x.max_steps}${x.blocked_reason?' · '+esc(x.blocked_reason):''}</small></div>`).join('')||'<span class="notice">No objectives.</span>'}catch(e){setOnline(false,'Status delayed')}clearTimeout(pollTimer);pollTimer=setTimeout(poll,5000)}function startPoll(){clearTimeout(pollTimer);poll()}function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}async function testModel(){try{const d=await api('/model/test',{method:'POST'});$('testResult').textContent=d.ok?'AI connected: '+d.active_model:'AI failed: '+d.last_error}catch(e){$('testResult').textContent=e.message}}async function testConnections(){try{const d=await api('/connections/test',{method:'POST'});$('testResult').textContent=`GitHub ${d.github.status}; Render ${d.render.status}`}catch(e){$('testResult').textContent=e.message}}
$('loginBtn').onclick=login;$('pw').onkeydown=e=>{if(e.key==='Enter')login()};$('sendBtn').onclick=()=>sendConversation();$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendConversation()}};$('objectiveBtn').onclick=runObjective;$('micBtn').onclick=manualMic;$('wakeBtn').onclick=toggleWake;$('stopVoiceBtn').onclick=()=>stopVoice();$('clearBtn').onclick=()=>{$('transcript').innerHTML='';history=[];addMsg('system','Conversation cleared.')};$('modelBtn').onclick=testModel;$('connBtn').onclick=testConnections;boot();</script></body></html>'''
